/// What to wait for after creating, copying, or starting a VM.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
#[non_exhaustive]
pub enum WaitUntil {
    /// Until it runs commands over SSH (by default). Requires ssh
    /// permission.
    #[default]
    Ssh,
    /// Until its setup script (exeuntu's exe-setup.service) has finished,
    /// too. A failed script is [`VmNotReady`] with
    /// [`setup`](VmNotReady::setup) set; so is a script on an image without
    /// that unit (anything not built on exeuntu), which never runs.
    Setup,
    /// Not at all: until exe.dev has created it.
    Created,
}

impl WaitUntil {
    pub(crate) fn timeout(self, timeout: Option<Duration>) -> Result<Duration> {
        match timeout {
            Some(t) if t.is_zero() => Err(Error::invalid("timeout must be positive")),
            Some(t) => Ok(t),
            None if self == WaitUntil::Setup => Ok(Duration::from_secs(600)),
            None => Ok(Duration::from_secs(60)),
        }
    }
}

/// How a command run on a VM ended, and what it wrote.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CommandResult {
    /// Its exit status. A command killed by a signal has 128 plus the
    /// signal's number, as in a shell.
    pub exit_code: i32,
    /// Its standard output, unless [`Run::capture`] was false.
    pub stdout: Vec<u8>,
    /// Its standard error, unless [`Run::capture`] was false.
    pub stderr: Vec<u8>,
    /// Whether output was captured.
    pub captured: bool,
}

impl CommandResult {
    /// Whether the exit status is 0.
    pub fn success(&self) -> bool {
        self.exit_code == 0
    }

    /// Standard output as text; invalid UTF-8 becomes U+FFFD.
    pub fn stdout_lossy(&self) -> String {
        String::from_utf8_lossy(&self.stdout).into_owned()
    }

    /// Standard error as text; invalid UTF-8 becomes U+FFFD.
    pub fn stderr_lossy(&self) -> String {
        String::from_utf8_lossy(&self.stderr).into_owned()
    }

    /// Self, or [`Error::Command`] if the exit status is not 0.
    pub fn check(self) -> Result<CommandResult> {
        if self.success() {
            Ok(self)
        } else {
            Err(Error::Command(Box::new(CommandError { result: self })))
        }
    }
}

/// A VM on exe.dev.
///
/// Get one from [`Client::new_vm`](crate::Client::new_vm),
/// [`Client::vms`](crate::Client::vms), [`Client::vm`](crate::Client::vm),
/// or [`Vm::copy`]. Its attributes are a snapshot: the SDK's own operations
/// keep them current, and [`refresh`](Vm::refresh) fetches the rest. It is
/// cheap to clone; a clone's snapshot is its own.
///
/// Dropping a `Vm` does not delete the VM: [`delete`](Vm::delete) does.
#[derive(Clone)]
